      NewsModel(title: 'Из кэша 2', link: 'https://example.com/cached/2', date: DateTime.now()),
    ];

    final freshItems = [
      NewsModel(title: 'Из сети 1', link: 'https://example.com/fresh/1', date: DateTime.now()),
      NewsModel(title: 'Из сети 2', link: 'https://example.com/fresh/2', date: DateTime.now()),
      NewsModel(title: 'Из сети 3', link: 'https://example.com/fresh/3', date: DateTime.now()),
    ];

    Widget buildPage() => buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        );

    setUp(() {
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
          .thenAnswer((_) async => freshItems);
      when(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => cachedItems);
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
    });

    testWidgets('should load fresh news from network when cache is empty', (WidgetTester tester) async {
      when(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => []);

      await tester.pumpWidget(buildPage());
      await tester.pumpAndSettle();

      expect(find.text('Из сети 1'), findsOneWidget);
      expect(find.text('Из сети 2'), findsOneWidget);
      expect(find.text('Из сети 3'), findsOneWidget);
      expect(find.text('Из кэша 1'), findsNothing);

      verify(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).called(1);
      verify(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true))).called(1);
    });

    testWidgets('should show cached news immediately and then refresh from network', (WidgetTester tester) async {
      final Completer<List<NewsModel>> networkCompleter = Completer<List<NewsModel>>();
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
          .thenAnswer((_) => networkCompleter.future);

      await tester.pumpWidget(buildPage());
      await tester.pump();

      // Кэш отрисован до ответа сети.
      expect(find.text('Из кэша 1'), findsOneWidget);
      expect(find.text('Из сети 1'), findsNothing);

      networkCompleter.complete(freshItems);
      await tester.pumpAndSettle();

      // Лента обновилась данными из сети.
      expect(find.text('Из сети 1'), findsOneWidget);
      expect(find.text('Из сети 3'), findsOneWidget);
      expect(find.text('Из кэша 1'), findsNothing);
    });

    testWidgets('should keep cached news when network request fails', (WidgetTester tester) async {
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
          .thenAnswer((_) => Future<List<NewsModel>>.error(Exception('network is unavailable')));

      await tester.pumpWidget(buildPage());
      await tester.pumpAndSettle();

      expect(find.text('Из кэша 1'), findsOneWidget);
      expect(find.text('Из кэша 2'), findsOneWidget);
    });

    testWidgets('should not throw when page is disposed before network response', (WidgetTester tester) async {
      final Completer<List<NewsModel>> networkCompleter = Completer<List<NewsModel>>();
      when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
          .thenAnswer((_) => networkCompleter.future);

      await tester.pumpWidget(buildPage());
      await tester.pump();

      await tester.pumpWidget(const SizedBox.shrink());

      networkCompleter.complete(freshItems);
      await tester.pumpAndSettle();

      expect(tester.takeException(), isNull);
    });
  });
}

